*/
scwin.btn_goDelete_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goDelete_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.go_delete()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91000.btn_goDelete_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91000.btn_print_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_self_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_self_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_self_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91000.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_go_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_go_modify = async function () {
    const sbmOptions = {
        id: "tx_go_modify",
        method: "post",
        action: "/stdcd/stdcdModify.do?method=stdcdModify",
        ref: "dma_goModifyReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf91000.tx_go_modify" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.open_password
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_type
 * @returns
 * @hidden N
*/
scwin.open_password = function (ipt_type) {
    /* sdd-asis-lifecycle:begin open_password — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF91000 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue(ipt_type);
    fn_passwordWin(form);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.go_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.go_modify = async function () {
    /* sdd-asis-lifecycle:begin go_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF91000 || { elements: [] });
    form.action = "/stdcd/stdcdModify.do?method=stdcdModify";
    form.target = "_top";
    await scwin.tx_go_modify();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.go_delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.go_delete = function () {
    /* sdd-asis-lifecycle:begin go_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF91000 || { elements: [] });
    fn_stdCdDelWin(form);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = async function () {
    /* sdd-asis-lifecycle:begin fn_print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("주권 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent("dma_goModifyReq").get("stdCd");
        $.ajax({ type: "POST", async: false, url: "/srch/srch.do?method=srchReportCommonAjax&serviceName=srchReport2&std_cd=" + std_cd, data: {  }, success: async function(data) {
                    const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    const form = (document.newReportForm || { elements: [] });
                    for (key in result) {
                        if (form[camelize(key)]) {
                            form[camelize(key)].value = result[key];
                        }
                    }
                    await scwin.tx_fn_print();
                }, error: async function(request, status, error) {
                    await $c.win.alert("장애발생.");
                    return;
                }, complete: function() {

                } });
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.printOld
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.printOld = async function () {
    /* sdd-asis-lifecycle:begin fn_print_old — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("주권 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const formName = (document.JLDINF91000 || { elements: [] });
        const std_cd = $c.util.getComponent("dma_goModifyReq").get("stdCd");
        const rexName = "JLDINF91000";
        const dataType = "XML";
        const dataLocation = "/srch/srch.do?method=srchReport2&std_cd=" + std_cd;
        const dataXPath = "main/rpt1";
        const mktGubun = "1";
        fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);
    }
    /* sdd-asis-lifecycle:end */
};
